from taf.gnb.oam.ne3s.ws.components.connection.messages import (
    NotificationMsg, AttachmentType, NotificationType,
    NotificationGroup)


class FmRebuildNotification(NotificationMsg):
    """In NE3S/WS agent is responsible for sending a ne3s_fm_alarmRebuildNotification
    to all managers supporting fault management notifications when it has finished
    rebuilding its alarm table."""
    def __init__(self, *args, **kwargs):
        super(FmRebuildNotification, self).__init__(*args, **kwargs)

    @staticmethod
    def matches(soap, attachment):
        return (isinstance(soap, NotificationType.TransferNotification)
                and soap.notification_type == "ne3s_fm_rebuildNotification")


class ActiveFaults(NotificationMsg):
    def __init__(self, *args, **kwargs):
        super(ActiveFaults, self).__init__(*args, **kwargs)
        self.alarms = self.attachment.alarms

    @staticmethod
    def matches(soap, attachment):
        return (isinstance(soap, NotificationType.ReportOperationStatus)
                and isinstance(attachment, AttachmentType.Ofas))


class FMNotificationGroup(NotificationGroup):
    NOTIFICATIONS = (FmRebuildNotification, ActiveFaults)
    QUEUE_IDS = ("common_queue", "fm_queue")
